/// The summary the usage header prints, from the usage golden and the inventory.
pub fn summary(tool: &str) -> Option<&'static str> {
    match tool {
        "CountReads" => Some("Count and print to standard output (and optionally to a file) the total number of reads in a SAM/BAM/CRAM file"),
        "CountVariants" => Some("Counts variant records in a VCF file, regardless of filter status."),
        "PrintReads" => Some("Print reads in the SAM/BAM/CRAM file"),
        "ApplyBQSR" => Some("Apply base quality score recalibration"),
        "SelectVariants" => Some("Select a subset of variants from a VCF file"),
        "IndexFeatureFile" => Some("Creates an index for a feature file, e.g. VCF or BED file."),
        "GatherVcfsCloud" => Some("Gathers multiple VCF files from a scatter operation into a single VCF file. Input files must be supplied in genomic\norder and must not have events at overlapping positions."),
        "CountBases" => Some("Count bases in a SAM/BAM/CRAM file"),
        "FlagStat" => Some("Accumulate flag statistics given a BAM file"),
        "CountBasesInReference" => Some("Count the numbers of each base in a reference file"),
        "SplitIntervals" => Some("Split intervals into sub-interval files."),
        "Pileup" => Some("Prints read alignments in samtools pileup format"),
        "PreprocessIntervals" => Some("Prepares bins for coverage collection"),
        "PrintDistantMates" => Some("Unmaps reads with distant mates."),
        "GetSampleName" => Some("Emit a single sample name"),
        "CompareIntervalLists" => Some("Compare two interval lists to see if they are equal"),
        "FixMisencodedBaseQualityReads" => Some("Fix Illumina base quality scores in a SAM/BAM/CRAM file"),
        "PrintBGZFBlockInformation" => Some("Print information about the compressed blocks in a BGZF format file"),
        "CreateHadoopBamSplittingIndex" => Some("Create a Hadoop BAM splitting index and optionally a BAM index from a BAM file"),
        _ => None,
    }
}

/// Whether a tool prints a banner above its usage line, and which.
pub fn maturity(tool: &str) -> Maturity {
    match tool {
        "CountReads" => Maturity::Released,
        "CountVariants" => Maturity::Released,
        "PrintReads" => Maturity::Released,
        "ApplyBQSR" => Maturity::Released,
        "SelectVariants" => Maturity::Released,
        "IndexFeatureFile" => Maturity::Released,
        "GatherVcfsCloud" => Maturity::Released,
        "CountBases" => Maturity::Released,
        "FlagStat" => Maturity::Released,
        "CountBasesInReference" => Maturity::Released,
        "SplitIntervals" => Maturity::Released,
        "Pileup" => Maturity::Released,
        "PreprocessIntervals" => Maturity::Released,
        "PrintDistantMates" => Maturity::Released,
        "GetSampleName" => Maturity::Released,
        "CompareIntervalLists" => Maturity::Released,
        "FixMisencodedBaseQualityReads" => Maturity::Released,
        "PrintBGZFBlockInformation" => Maturity::Experimental,
        "CreateHadoopBamSplittingIndex" => Maturity::Beta,
        _ => Maturity::Released,
    }
}

